# Body of Supplementary Table S4 (Models 1 to 3 by input variant and calculator, published sample) from the model results:
# the published-SRI refit from variants4_models.csv and the five input variants from na_models_all.csv (combine_na_models.R).
# Env: SRI_PROJECT_ROOT (working-tree root), FRAG_DIR (folder with the two CSV files), NUM_DIR (manuscript numbers folder).
suppressMessages(library(data.table))
base <- Sys.getenv("SRI_PROJECT_ROOT", getwd())
fragdir <- Sys.getenv("FRAG_DIR", file.path(base, "01_recompute_SRI/intermediate/revision_2026-10_results/frag")); numdir <- Sys.getenv("NUM_DIR", getwd())
pub <- fread(file.path(fragdir, "variants4_models.csv"))[grepl("^published", variant)]
all <- fread(file.path(fragdir, "na_models_all.csv"))[calculator %in% c("SRI_hand", "SRI_GGIR", "SRI_sleepregE5", "SRI_sleepregE3")]
vlab <- c(raw = "Released classification, unsmoothed", maj1h50 = "Rolling majority, 1 h", ggir1h80 = "\\texttt{GGIR} SRI1 smoothing, 1 h, 80\\%", bridge2 = "Awakenings $<$30 min bridged", spt2 = "Main sleep period only")
clab <- c(SRI_hand = "Phillips formula", SRI_GGIR = "\\texttt{GGIR}", SRI_sleepregE5 = "\\texttt{sleepreg}, 5 days", SRI_sleepregE3 = "\\texttt{sleepreg}, 3 days")
strip <- function(x) sub("^(Male|Female) ", "", x)
row <- function(input, calc, r) sprintf("%s & %s & %d & %s & %s & %s & %s \\\\", input, calc, r$n, r$M1, r$M2, strip(r$M3_other), strip(r$M3_ref))
rows <- row("Published SRI", "published implementation", pub)
for (v in names(vlab)) for (cc in names(clab)) { r <- all[variant == v & calculator == cc]; stopifnot(nrow(r) == 1)
  rows <- c(rows, row(if (cc == "SRI_hand") vlab[[v]] else "", clab[[cc]], r)) }
writeLines(c("% generated by make_tab_assoc.R from variants4_models.csv and na_models_all.csv; do not edit",
             "\\begin{tabular}{llrcccc}", "\\toprule",
             "Input & Calculator & $n$ & Model 1 (age, sex) & Model 2 (fully adjusted) & Model 3, women & Model 3, men \\\\", "\\midrule",
             rows, "\\bottomrule", "\\end{tabular}"), file.path(numdir, "tab_assoc.tex"))
cat("written:", file.path(numdir, "tab_assoc.tex"), "rows:", length(rows), "\n")
